:root {
  --var: 'Arial Black', Helvetica, sans-serif;
}

/**
 * Matches: token.type === 'typography'
 * Returns:
 */
:root {
  --var: italic 400 1.2rem/1.5 'Fira Sans', sans-serif;
}

